// Downloadable ad templates: real SVG files in public/ad-templates/ (generated by scripts/gen-ad-templates.mjs).
// Open in Canva, Figma, Photopea or any editor; text is live (not outlined) so it can be edited.
export interface AdTemplateLayout { id: string; name: string; best: string }
export interface AdTemplateSize { id: string; label: string; w: number; h: number }
export const TEMPLATE_LAYOUTS: readonly AdTemplateLayout[] = [
  { id: "offer", name: "Big offer", best: "A single discount or free-quote offer." },
  { id: "photo-headline", name: "Photo with headline bar", best: "Before/after or job photos with one line of text." },
  { id: "review", name: "Customer review", best: "A real review quote with a star line." },
  { id: "announcement", name: "Event or opening", best: "Seasonal events, openings and deadlines." },
];
export const TEMPLATE_SIZES: readonly AdTemplateSize[] = [
  { id: "square", label: "Square 1080x1080", w: 1080, h: 1080 },
  { id: "portrait", label: "Portrait 1080x1350", w: 1080, h: 1350 },
  { id: "story", label: "Story 1080x1920", w: 1080, h: 1920 },
];
export const templatePath = (layout: string, size: string) => `/ad-templates/komendly-${layout}-${size}.svg`;
export const allTemplatePaths = () => TEMPLATE_LAYOUTS.flatMap((l) => TEMPLATE_SIZES.map((s) => templatePath(l.id, s.id)));
